"use client"

import * as React from "react"
import { CheckCircle, XCircle, ChevronDown, ChevronRight, Lightbulb } from "lucide-react"
import { cn } from "@aetherstack/utils"
import {
  Button,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  Progress,
  ScrollArea,
} from "@aetherstack/ui"

interface AgentStep {
  id: string
  toolName: string
  status: "pending" | "running" | "done" | "error"
  args?: Record<string, unknown>
  result?: unknown
}

interface AgentWorkspaceProps {
  task?: string
  steps?: AgentStep[]
  reasoning?: string
  output?: string
  isRunning?: boolean
  className?: string
}

function StepIcon({ status }: { status: AgentStep["status"] }) {
  switch (status) {
    case "pending":
      return <span className="border-muted-foreground/40 h-4 w-4 shrink-0 rounded-full border-2" />
    case "running":
      return (
        <span className="border-primary h-4 w-4 shrink-0 animate-spin rounded-full border-2 border-t-transparent" />
      )
    case "done":
      return <CheckCircle className="h-4 w-4 shrink-0 text-green-500" />
    case "error":
      return <XCircle className="text-destructive h-4 w-4 shrink-0" />
  }
}

function StepItem({ step, index }: { step: AgentStep; index: number }) {
  const [open, setOpen] = React.useState(false)
  const hasDetails = step.args !== undefined || step.result !== undefined

  return (
    <div className="border-border overflow-hidden rounded-lg border">
      <button
        className="hover:bg-accent/50 flex w-full items-center gap-3 px-4 py-3 text-sm transition-colors"
        onClick={() => hasDetails && setOpen((o) => !o)}
        disabled={!hasDetails}
      >
        <span className="bg-muted text-muted-foreground flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-xs font-medium">
          {index + 1}
        </span>
        <StepIcon status={step.status} />
        <span className="flex-1 text-left font-mono font-medium">{step.toolName}</span>
        <span className="text-muted-foreground text-xs capitalize">{step.status}</span>
        {hasDetails &&
          (open ? (
            <ChevronDown className="text-muted-foreground h-4 w-4" />
          ) : (
            <ChevronRight className="text-muted-foreground h-4 w-4" />
          ))}
      </button>
      {open && hasDetails && (
        <div className="border-border space-y-3 border-t px-4 pb-4 pt-3">
          {step.args && (
            <div>
              <p className="text-muted-foreground mb-1 text-xs font-medium uppercase tracking-wide">
                Arguments
              </p>
              <pre className="bg-muted overflow-x-auto rounded p-3 font-mono text-xs">
                {JSON.stringify(step.args, null, 2)}
              </pre>
            </div>
          )}
          {step.result !== undefined && (
            <div>
              <p className="text-muted-foreground mb-1 text-xs font-medium uppercase tracking-wide">
                Result
              </p>
              <pre className="bg-muted overflow-x-auto rounded p-3 font-mono text-xs">
                {JSON.stringify(step.result, null, 2)}
              </pre>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function AgentWorkspace({
  task,
  steps = [],
  reasoning,
  output,
  isRunning = false,
  className,
}: AgentWorkspaceProps) {
  const [reasoningOpen, setReasoningOpen] = React.useState(false)
  const doneCount = steps.filter((s) => s.status === "done").length
  const progress = steps.length > 0 ? (doneCount / steps.length) * 100 : 0

  return (
    <div className={cn("flex flex-col gap-4 p-4", className)}>
      {task && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Task</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-sm">{task}</p>
            {isRunning && steps.length > 0 && (
              <div className="mt-3 flex flex-col gap-1.5">
                <div className="text-muted-foreground flex items-center justify-between text-xs">
                  <span>Progress</span>
                  <span>
                    {doneCount} / {steps.length} steps
                  </span>
                </div>
                <Progress value={progress} className="h-1.5" />
              </div>
            )}
          </CardContent>
        </Card>
      )}

      <div className="flex gap-4">
        <div className="flex flex-1 flex-col gap-3">
          <h3 className="text-muted-foreground text-sm font-medium uppercase tracking-wide">
            Tool calls
          </h3>
          <ScrollArea className="max-h-80">
            <div className="flex flex-col gap-2 pr-2">
              {steps.map((step, i) => (
                <StepItem key={step.id} step={step} index={i} />
              ))}
              {steps.length === 0 && (
                <p className="text-muted-foreground py-4 text-center text-sm">No steps yet</p>
              )}
            </div>
          </ScrollArea>
        </div>

        {reasoning && (
          <div className="w-64 shrink-0">
            <Card>
              <CardHeader className="pb-2">
                <button
                  className="text-muted-foreground hover:text-foreground flex w-full items-center gap-2 text-sm font-medium transition-colors"
                  onClick={() => setReasoningOpen((o) => !o)}
                >
                  <Lightbulb className="h-4 w-4 shrink-0" />
                  Reasoning
                  <span className="ml-auto">
                    {reasoningOpen ? (
                      <ChevronDown className="h-4 w-4" />
                    ) : (
                      <ChevronRight className="h-4 w-4" />
                    )}
                  </span>
                </button>
              </CardHeader>
              {reasoningOpen && (
                <CardContent>
                  <div className="bg-muted text-muted-foreground max-h-40 overflow-y-auto whitespace-pre-wrap rounded p-3 font-mono text-xs leading-relaxed">
                    {reasoning}
                  </div>
                </CardContent>
              )}
            </Card>
          </div>
        )}
      </div>

      {output && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Output</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="bg-muted overflow-x-auto whitespace-pre-wrap rounded p-3 font-mono text-sm">
              {output}
            </div>
            <Button
              variant="outline"
              size="sm"
              className="mt-3"
              onClick={() => void navigator.clipboard.writeText(output)}
            >
              Copy output
            </Button>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

export { AgentWorkspace }

"use client"

import * as React from "react"
import { cn } from "@aetherstack/utils"
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetClose } from "@aetherstack/ui"

interface AIAssistantPanelProps {
  open?: boolean
  onOpenChange?: (open: boolean) => void
  title?: string
  children?: React.ReactNode
  footer?: React.ReactNode
  side?: "right" | "left"
  className?: string
}

function AIAssistantPanel({
  open,
  onOpenChange,
  title = "AI Assistant",
  children,
  footer,
  side = "right",
  className,
}: AIAssistantPanelProps) {
  return (
    <Sheet
      {...(open !== undefined ? { open } : {})}
      {...(onOpenChange !== undefined ? { onOpenChange } : {})}
    >
      <SheetContent
        side={side}
        className={cn("flex w-[420px] max-w-full flex-col p-0 sm:max-w-[420px]", className)}
      >
        <SheetHeader className="border-border flex-row items-center justify-between border-b px-4 py-3">
          <SheetTitle className="text-base">{title}</SheetTitle>
          <SheetClose className="ring-offset-background focus:ring-ring rounded-sm opacity-70 transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-offset-2" />
        </SheetHeader>

        <div className="flex-1 overflow-y-auto">{children}</div>

        {footer && <div className="border-border shrink-0 border-t p-4">{footer}</div>}
      </SheetContent>
    </Sheet>
  )
}

export { AIAssistantPanel }

"use client"

import * as React from "react"
import { cn } from "@aetherstack/utils"
import { Button, Card, CardContent, CardHeader, CardTitle, CardDescription } from "@aetherstack/ui"
import { Stepper } from "@aetherstack/patterns"

interface OnboardingStep {
  id: string
  title: string
  description?: string
  content: React.ReactNode
}

const DEFAULT_STEPS: OnboardingStep[] = [
  {
    id: "api-key",
    title: "Add your API key",
    description: "Connect your AI provider",
    content: <p className="text-muted-foreground text-sm">Enter your API key to get started.</p>,
  },
  {
    id: "model",
    title: "Choose a model",
    description: "Select your preferred AI model",
    content: <p className="text-muted-foreground text-sm">Pick a model that fits your needs.</p>,
  },
  {
    id: "try",
    title: "Try an example",
    description: "See AI in action",
    content: (
      <p className="text-muted-foreground text-sm">Send your first message to see how it works.</p>
    ),
  },
]

interface AIOnboardingProps {
  steps?: OnboardingStep[]
  onComplete?: () => void
  className?: string
}

function AIOnboarding({ steps = DEFAULT_STEPS, onComplete, className }: AIOnboardingProps) {
  const [currentStep, setCurrentStep] = React.useState(0)
  const step = steps[currentStep]
  const isLast = currentStep === steps.length - 1

  function next() {
    if (isLast) {
      onComplete?.()
    } else {
      setCurrentStep((s) => s + 1)
    }
  }

  function back() {
    setCurrentStep((s) => Math.max(0, s - 1))
  }

  const stepperItems = steps.map((s) => ({
    id: s.id,
    label: s.title,
    ...(s.description !== undefined ? { description: s.description } : {}),
  }))

  return (
    <div className={cn("mx-auto flex max-w-lg flex-col gap-6 py-8", className)}>
      <Stepper steps={stepperItems} currentStep={currentStep} orientation="horizontal" />

      {step && (
        <Card>
          <CardHeader>
            <CardTitle>{step.title}</CardTitle>
            {step.description && <CardDescription>{step.description}</CardDescription>}
          </CardHeader>
          <CardContent className="flex flex-col gap-4">
            {step.content}
            <div className="flex items-center justify-between pt-2">
              <Button variant="outline" onClick={back} disabled={currentStep === 0}>
                Back
              </Button>
              <Button onClick={next}>{isLast ? "Get started" : "Continue"}</Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

export { AIOnboarding }

"use client"

import { cn } from "@aetherstack/utils"
import { Card, CardContent, CardHeader, CardTitle } from "@aetherstack/ui"

interface UsageStats {
  totalRequests: number
  totalTokens: number
  estimatedCost: number
  period?: string
}

interface ModelUsage {
  model: string
  tokens: number
  cost: number
}

interface DailyUsage {
  date: string
  requests: number
  tokens: number
}

interface AIUsageDashboardProps {
  stats?: UsageStats
  tokensByModel?: ModelUsage[]
  requestsOverTime?: DailyUsage[]
  className?: string
}

function formatNumber(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`
  return n.toString()
}

function formatCost(n: number): string {
  return `$${n.toFixed(4)}`
}

interface MiniBarChartProps {
  data: { label: string; value: number }[]
  color?: string
}

function MiniBarChart({ data, color = "hsl(var(--primary))" }: MiniBarChartProps) {
  const max = Math.max(...data.map((d) => d.value), 1)
  const height = 80
  const barWidth = 100 / Math.max(data.length, 1)

  return (
    <div className="w-full overflow-x-auto">
      <svg
        viewBox={`0 0 100 ${height}`}
        preserveAspectRatio="none"
        className="w-full"
        style={{ height: `${height}px` }}
        aria-label="Bar chart"
      >
        {data.map((d, i) => {
          const barH = (d.value / max) * (height - 4)
          const x = i * barWidth + barWidth * 0.1
          const w = barWidth * 0.8
          return (
            <rect
              key={i}
              x={x}
              y={height - barH}
              width={w}
              height={barH}
              fill={color}
              rx="1"
              opacity="0.85"
            >
              <title>{`${d.label}: ${formatNumber(d.value)}`}</title>
            </rect>
          )
        })}
      </svg>
      <div className="mt-1 flex justify-between">
        {data.length <= 7 ? (
          data.map((d, i) => (
            <span
              key={i}
              className="text-muted-foreground truncate text-xs"
              style={{ maxWidth: `${100 / data.length}%` }}
            >
              {d.label}
            </span>
          ))
        ) : (
          <>
            <span className="text-muted-foreground text-xs">{data[0]?.label}</span>
            <span className="text-muted-foreground text-xs">{data[data.length - 1]?.label}</span>
          </>
        )}
      </div>
    </div>
  )
}

function AIUsageDashboard({
  stats,
  tokensByModel = [],
  requestsOverTime = [],
  className,
}: AIUsageDashboardProps) {
  const chartData = requestsOverTime.map((d) => ({
    label: d.date.slice(-5),
    value: d.requests,
  }))

  return (
    <div className={cn("flex flex-col gap-6", className)}>
      {stats && (
        <div className="grid gap-4 sm:grid-cols-3">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-muted-foreground text-sm font-medium">
                Total requests
                {stats.period && ` (${stats.period})`}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-2xl font-bold">{formatNumber(stats.totalRequests)}</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-muted-foreground text-sm font-medium">
                Total tokens
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-2xl font-bold">{formatNumber(stats.totalTokens)}</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-muted-foreground text-sm font-medium">
                Estimated cost
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-2xl font-bold">{formatCost(stats.estimatedCost)}</p>
            </CardContent>
          </Card>
        </div>
      )}

      {chartData.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Requests over time</CardTitle>
          </CardHeader>
          <CardContent>
            <MiniBarChart data={chartData} />
          </CardContent>
        </Card>
      )}

      {tokensByModel.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Usage by model</CardTitle>
          </CardHeader>
          <CardContent>
            <table className="w-full text-sm">
              <thead>
                <tr className="border-border border-b text-left">
                  <th className="text-muted-foreground pb-2 font-medium">Model</th>
                  <th className="text-muted-foreground pb-2 text-right font-medium">Tokens</th>
                  <th className="text-muted-foreground pb-2 text-right font-medium">Cost</th>
                </tr>
              </thead>
              <tbody>
                {tokensByModel.map((row, i) => (
                  <tr key={i} className="border-border/50 border-b last:border-0">
                    <td className="py-2 font-mono">{row.model}</td>
                    <td className="py-2 text-right tabular-nums">{formatNumber(row.tokens)}</td>
                    <td className="py-2 text-right tabular-nums">{formatCost(row.cost)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

export { AIUsageDashboard }

"use client"

import * as React from "react"
import { Menu } from "lucide-react"
import { cn } from "@aetherstack/utils"
import { Button, Sheet, SheetContent, SheetTrigger } from "@aetherstack/ui"

export interface AppHeaderNavItem {
  label: string
  href: string
  active?: boolean
}

export interface AppHeaderProps {
  logo?: React.ReactNode
  appName?: string
  navItems?: AppHeaderNavItem[]
  actions?: React.ReactNode
  className?: string
}

export function AppHeader({
  logo,
  appName = "App",
  navItems = [],
  actions,
  className,
}: AppHeaderProps) {
  return (
    <header
      className={cn(
        "border-border bg-background/95 sticky top-0 z-40 w-full border-b backdrop-blur-sm",
        className,
      )}
    >
      <div className="mx-auto flex h-14 max-w-screen-xl items-center gap-4 px-4 sm:px-6">
        {/* Logo / brand */}
        <div className="flex shrink-0 items-center gap-2">
          {logo}
          {appName && <span className="text-foreground text-sm font-semibold">{appName}</span>}
        </div>

        {/* Desktop nav */}
        {navItems.length > 0 && (
          <nav className="hidden flex-1 md:flex" aria-label="Main navigation">
            <ul className="flex items-center gap-1">
              {navItems.map((item, index) => (
                <li key={`${index}-${item.href}`}>
                  <Button
                    asChild
                    variant="ghost"
                    size="sm"
                    className={cn(
                      "text-sm",
                      item.active ? "text-foreground font-medium" : "text-muted-foreground",
                    )}
                  >
                    <a href={item.href} aria-current={item.active ? "page" : undefined}>
                      {item.label}
                    </a>
                  </Button>
                </li>
              ))}
            </ul>
          </nav>
        )}

        {/* Spacer when no nav */}
        {navItems.length === 0 && <div className="flex-1" />}

        {/* Desktop actions */}
        {actions && <div className="hidden items-center gap-2 md:flex">{actions}</div>}

        {/* Mobile hamburger */}
        {navItems.length > 0 && (
          <div className="flex flex-1 justify-end md:hidden">
            <Sheet>
              <SheetTrigger asChild>
                <Button variant="ghost" size="icon" aria-label="Open navigation">
                  <Menu className="h-5 w-5" />
                </Button>
              </SheetTrigger>
              <SheetContent side="left" className="w-64">
                <div className="flex items-center gap-2 pb-4">
                  {logo}
                  {appName && (
                    <span className="text-foreground text-sm font-semibold">{appName}</span>
                  )}
                </div>
                <nav aria-label="Mobile navigation">
                  <ul className="space-y-1">
                    {navItems.map((item, index) => (
                      <li key={`${index}-${item.href}`}>
                        <a
                          href={item.href}
                          aria-current={item.active ? "page" : undefined}
                          className={cn(
                            "flex w-full items-center rounded-md px-3 py-2 text-sm transition-colors",
                            item.active
                              ? "bg-accent text-accent-foreground font-medium"
                              : "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
                          )}
                        >
                          {item.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                </nav>
                {actions && <div className="mt-4 flex flex-col gap-2">{actions}</div>}
              </SheetContent>
            </Sheet>
          </div>
        )}
      </div>
    </header>
  )
}

"use client"

import { cn } from "@aetherstack/utils"
import { Button, Progress } from "@aetherstack/ui"

export interface BillingPlan {
  name: string
  price: string
  period: string
  features: string[]
}

export interface UsageMetric {
  label: string
  used: number
  limit: number
  unit?: string
}

export interface BillingOverviewProps {
  plan?: BillingPlan
  usage?: UsageMetric[]
  nextBillingDate?: string
  onUpgrade?: () => void
  onManageBilling?: () => void
  className?: string
}

const DEFAULT_PLAN: BillingPlan = {
  name: "Free",
  price: "$0",
  period: "month",
  features: ["Up to 3 projects", "1 team member", "Community support"],
}

export function BillingOverview({
  plan = DEFAULT_PLAN,
  usage = [],
  nextBillingDate,
  onUpgrade,
  onManageBilling,
  className,
}: BillingOverviewProps) {
  return (
    <div className={cn("w-full space-y-6", className)}>
      {/* Current plan card */}
      <div className="border-border bg-card rounded-xl border p-6 shadow-sm">
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-muted-foreground text-xs font-medium uppercase tracking-wider">
              Current plan
            </p>
            <h2 className="text-foreground mt-1 text-2xl font-bold">{plan.name}</h2>
            <p className="text-muted-foreground mt-0.5 text-sm">
              <span className="text-foreground text-xl font-semibold">{plan.price}</span>
              &nbsp;/ {plan.period}
            </p>
          </div>
          {onUpgrade && (
            <Button size="sm" onClick={onUpgrade} className="shrink-0">
              Upgrade plan
            </Button>
          )}
        </div>

        {/* Features */}
        {plan.features.length > 0 && (
          <ul className="mt-4 space-y-1.5">
            {plan.features.map((f) => (
              <li key={f} className="text-muted-foreground flex items-center gap-2 text-sm">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  className="text-primary shrink-0"
                  aria-hidden
                >
                  <polyline points="20 6 9 17 4 12" />
                </svg>
                {f}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Usage meters */}
      {usage.length > 0 && (
        <div className="border-border bg-card rounded-xl border p-6 shadow-sm">
          <h3 className="text-foreground mb-4 text-sm font-semibold">Usage</h3>
          <div className="space-y-4">
            {usage.map((metric) => {
              const pct =
                metric.limit > 0 ? Math.min(100, Math.round((metric.used / metric.limit) * 100)) : 0
              const isNearLimit = pct >= 80
              return (
                <div key={metric.label}>
                  <div className="mb-1.5 flex items-center justify-between text-sm">
                    <span className="text-foreground font-medium">{metric.label}</span>
                    <span
                      className={cn(
                        "text-muted-foreground",
                        isNearLimit && "text-destructive font-medium",
                      )}
                    >
                      {metric.used.toLocaleString()}
                      {metric.unit ? ` ${metric.unit}` : ""} / {metric.limit.toLocaleString()}
                      {metric.unit ? ` ${metric.unit}` : ""}
                    </span>
                  </div>
                  <Progress
                    value={pct}
                    className="h-2"
                    indicatorClassName={cn(isNearLimit && "bg-destructive")}
                  />
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* Footer: next billing + manage button */}
      <div className="border-border bg-card flex items-center justify-between gap-4 rounded-xl border px-6 py-4 shadow-sm">
        {nextBillingDate ? (
          <p className="text-muted-foreground text-sm">
            Next billing date:{" "}
            <span className="text-foreground font-medium">{nextBillingDate}</span>
          </p>
        ) : (
          <p className="text-muted-foreground text-sm">No upcoming charges.</p>
        )}
        {onManageBilling && (
          <Button variant="outline" size="sm" onClick={onManageBilling}>
            Manage billing
          </Button>
        )}
      </div>
    </div>
  )
}

import { cn } from "@aetherstack/utils"
import { Badge, Separator } from "@aetherstack/ui"

export type ChangeType = "added" | "changed" | "fixed" | "removed"

export interface ChangeGroup {
  type: ChangeType
  items: string[]
}

export interface ChangelogEntry {
  id: string
  version?: string
  date: string
  title: string
  description?: string
  tags?: string[]
  changes?: ChangeGroup[]
}

export interface ChangelogBlockProps {
  entries: ChangelogEntry[]
  className?: string
}

const changeTypeConfig: Record<
  ChangeType,
  { label: string; variant: "default" | "secondary" | "destructive" | "outline" }
> = {
  added: { label: "Added", variant: "default" },
  changed: { label: "Changed", variant: "secondary" },
  fixed: { label: "Fixed", variant: "outline" },
  removed: { label: "Removed", variant: "destructive" },
}

export function ChangelogBlock({ entries, className }: ChangelogBlockProps) {
  return (
    <div className={cn("w-full", className)}>
      <div className="relative mx-auto max-w-3xl space-y-0">
        {entries.map((entry, i) => (
          <div key={entry.id} className="relative flex gap-6 pb-10">
            {/* Timeline line */}
            <div className="flex flex-col items-center">
              <div className="border-primary bg-background mt-1.5 h-3 w-3 shrink-0 rounded-full border-2" />
              {i < entries.length - 1 && <div className="bg-border mt-1 w-px flex-1" />}
            </div>

            {/* Content */}
            <div className="flex-1 pb-2">
              <div className="flex flex-wrap items-center gap-2">
                {entry.version && (
                  <Badge variant="secondary" className="font-mono text-xs">
                    {entry.version}
                  </Badge>
                )}
                <time className="text-muted-foreground text-xs">{entry.date}</time>
                {entry.tags?.map((tag) => (
                  <Badge key={tag} variant="outline" className="text-xs">
                    {tag}
                  </Badge>
                ))}
              </div>

              <h3 className="text-foreground mt-2 text-base font-semibold">{entry.title}</h3>

              {entry.description && (
                <p className="text-muted-foreground mt-1.5 text-sm">{entry.description}</p>
              )}

              {entry.changes && entry.changes.length > 0 && (
                <div className="mt-4 space-y-3">
                  {entry.changes.map((group) => {
                    const config = changeTypeConfig[group.type]
                    return (
                      <div key={group.type}>
                        <div className="mb-1.5 flex items-center gap-2">
                          <Badge variant={config.variant} className="text-xs">
                            {config.label}
                          </Badge>
                        </div>
                        <ul className="space-y-1 pl-1">
                          {group.items.map((item, j) => (
                            <li key={j} className="text-foreground flex items-start gap-2 text-sm">
                              <span
                                className="bg-muted-foreground mt-2 h-1 w-1 shrink-0 rounded-full"
                                aria-hidden
                              />
                              {item}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )
                  })}
                </div>
              )}

              {i < entries.length - 1 && <Separator className="mt-6 hidden" />}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

