  secondaryCta?: CTASectionCta
  variant?: "default" | "muted" | "primary"
  className?: string
}

export function CTASection({
  headline,
  subheading,
  primaryCta,
  secondaryCta,
  variant = "default",
  className,
}: CTASectionProps) {
  return (
    <section
      className={cn(
        "w-full px-4 py-16",
        variant === "primary" && "bg-primary text-primary-foreground",
