import * as React from "react"
import { cn } from "@aetherstack/utils"
import { Checkbox } from "@aetherstack/ui"

export interface OnboardingStep {
  id: string
  title: string
  description?: string
  completed?: boolean
  href?: string
}

export interface OnboardingChecklistProps {
  steps: OnboardingStep[]
  title?: string
  description?: string
  onStepToggle?: (id: string, completed: boolean) => void
  className?: string
}

export function OnboardingChecklist({
  steps,
  title = "Get started",
  description = "Complete these steps to set up your workspace.",
  onStepToggle,
  className,
}: OnboardingChecklistProps) {
  const [localSteps, setLocalSteps] = React.useState<OnboardingStep[]>(steps)
  const [hideCompleted, setHideCompleted] = React.useState(false)

  React.useEffect(() => {
    setLocalSteps(steps)
  }, [steps])

  const completed = localSteps.filter((s) => s.completed).length
  const total = localSteps.length
  const progressPct = total === 0 ? 0 : Math.round((completed / total) * 100)

  function handleToggle(id: string) {
    setLocalSteps((prev) => prev.map((s) => (s.id === id ? { ...s, completed: !s.completed } : s)))
    const step = localSteps.find((s) => s.id === id)
    if (step) onStepToggle?.(id, !step.completed)
  }

  const visibleSteps = hideCompleted ? localSteps.filter((s) => !s.completed) : localSteps

  return (
    <div className={cn("border-border bg-card w-full rounded-xl border p-6 shadow-sm", className)}>
      {/* Header */}
      <div className="mb-4">
        <div className="flex items-center justify-between">
          <h2 className="text-foreground text-base font-semibold">{title}</h2>
          <span className="text-muted-foreground text-xs">
            {completed} of {total} completed
          </span>
        </div>
        {description && <p className="text-muted-foreground mt-1 text-sm">{description}</p>}
      </div>

      {/* Progress bar */}
      <div className="bg-muted mb-5 h-1.5 w-full overflow-hidden rounded-full">
        <div
          className="bg-primary h-1.5 rounded-full transition-all duration-500"
          style={{ width: `${progressPct}%` }}
        />
      </div>

      {/* Steps */}
      <ol className="space-y-3">
        {visibleSteps.map((step) => (
          <li
            key={step.id}
            className={cn(
              "flex items-start gap-3 rounded-lg border border-transparent p-3 transition-colors",
              step.completed ? "opacity-60" : "hover:border-border hover:bg-muted/40",
            )}
          >
            <Checkbox
              id={`step-${step.id}`}
              checked={Boolean(step.completed)}
              onCheckedChange={() => handleToggle(step.id)}
              className="mt-0.5 shrink-0"
            />
            <div className="min-w-0 flex-1">
              <label
                htmlFor={`step-${step.id}`}
                className={cn(
                  "block cursor-pointer text-sm font-medium",
                  step.completed ? "text-muted-foreground line-through" : "text-foreground",
                )}
              >
                {step.title}
              </label>
              {step.description && (
                <p className="text-muted-foreground mt-0.5 text-xs">{step.description}</p>
              )}
              {step.href && !step.completed && (
                <a
                  href={step.href}
                  className="text-primary mt-1 inline-block text-xs font-medium underline-offset-4 hover:underline"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Learn more →
                </a>
              )}
            </div>
          </li>
        ))}
      </ol>

      {/* Toggle completed */}
      {localSteps.some((s) => s.completed) && (
        <button
          type="button"
          onClick={() => setHideCompleted((v) => !v)}
          className="text-muted-foreground mt-4 text-xs underline-offset-4 hover:underline focus-visible:outline-none"
        >
          {hideCompleted ? "Show completed steps" : "Hide completed steps"}
        </button>
      )}
    </div>
  )
}

import * as React from "react"
import { Check, Minus } from "lucide-react"
import { cn } from "@aetherstack/utils"
import { Badge, Button } from "@aetherstack/ui"

export interface ComparisonTier {
  id: string
  name: string
  price?: string
  period?: string
  highlight?: boolean
  cta?: { label: string; href: string }
}

export interface ComparisonFeature {
  category?: string
  label: string
  tiers: Record<string, boolean | string | React.ReactNode>
}

export interface PricingComparisonProps {
  tiers: ComparisonTier[]
  features: ComparisonFeature[]
  className?: string
}

function FeatureValue({ value }: { value: boolean | string | React.ReactNode }) {
  if (value === true) {
    return (
      <span className="flex justify-center" aria-label="Included">
        <Check className="text-primary h-4 w-4" aria-hidden />
      </span>
    )
  }
  if (value === false) {
    return (
      <span className="flex justify-center" aria-label="Not included">
        <Minus className="text-muted-foreground/40 h-4 w-4" aria-hidden />
      </span>
    )
  }
  return <span className="text-foreground text-center text-sm">{value as React.ReactNode}</span>
}

export function PricingComparison({ tiers, features, className }: PricingComparisonProps) {
  const categoryGroups = features.reduce<
    { category: string | undefined; items: ComparisonFeature[] }[]
  >((acc, feature) => {
    const last = acc[acc.length - 1]
    if (last && last.category === feature.category) {
      last.items.push(feature)
    } else {
      acc.push({ category: feature.category, items: [feature] })
    }
    return acc
  }, [])

  return (
    <div className={cn("w-full overflow-x-auto", className)}>
      <table className="w-full min-w-[640px] border-collapse">
        {/* Header */}
        <thead>
          <tr>
            <th className="text-muted-foreground w-48 pb-4 text-left text-sm font-medium" />
            {tiers.map((tier) => (
              <th
                key={tier.id}
                className={cn("pb-4 text-center", tier.highlight && "bg-primary/5 rounded-t-lg")}
              >
                <div
                  className={cn(
                    "flex flex-col items-center gap-2 px-4 pb-2 pt-4",
                    tier.highlight && "border-primary rounded-t-lg border-x border-t",
                  )}
                >
                  <div className="flex items-center gap-2">
                    <span className="text-foreground text-sm font-semibold">{tier.name}</span>
                    {tier.highlight && <Badge className="text-xs">Popular</Badge>}
                  </div>
                  {tier.price && (
                    <div className="flex items-end gap-1">
                      <span className="text-foreground text-2xl font-bold tracking-tight">
                        {tier.price}
                      </span>
                      {tier.period && (
                        <span className="text-muted-foreground mb-0.5 text-xs">
                          / {tier.period}
                        </span>
                      )}
                    </div>
                  )}
                  {tier.cta && (
                    <Button
                      asChild
                      size="sm"
                      variant={tier.highlight ? "default" : "outline"}
                      className="w-full"
                    >
                      <a href={tier.cta.href}>{tier.cta.label}</a>
                    </Button>
                  )}
                </div>
              </th>
            ))}
          </tr>
        </thead>

        {/* Body */}
        <tbody>
          {categoryGroups.map((group, gi) => (
            <React.Fragment key={gi}>
              {group.category && (
                <tr>
                  <td
                    colSpan={tiers.length + 1}
                    className="border-border text-muted-foreground border-t pb-2 pt-6 text-xs font-semibold uppercase tracking-wider"
                  >
                    {group.category}
                  </td>
                </tr>
              )}
              {group.items.map((feature, fi) => (
                <tr key={fi} className="border-border/50 group border-t">
                  <td className="text-foreground py-3 pr-4 text-sm">{feature.label}</td>
                  {tiers.map((tier) => (
                    <td
                      key={tier.id}
                      className={cn(
                        "px-4 py-3 text-center",
                        tier.highlight && "bg-primary/5 border-primary/30 border-x",
                      )}
                    >
                      <FeatureValue value={feature.tiers[tier.id] ?? false} />
                    </td>
                  ))}
                </tr>
              ))}
            </React.Fragment>
          ))}

          {/* Bottom border for highlighted column */}
          <tr>
            <td />
            {tiers.map((tier) => (
              <td
                key={tier.id}
                className={cn(tier.highlight && "border-primary rounded-b-lg border-x border-b")}
              />
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  )
}

