import * as React from "react"
import { cn } from "@aetherstack/utils"
import { Badge } from "@aetherstack/ui"

// ── Types ─────────────────────────────────────────────────────────────────────

export interface KanbanItem {
  id: string
  title: string
  description?: string
  badge?: string
}

export interface KanbanCardProps {
  item: KanbanItem
  className?: string
}

export interface KanbanColumnProps {
  title: string
  items: KanbanItem[]
  onDrop?: (item: KanbanItem, columnTitle: string) => void
  className?: string
}

export interface KanbanBoardProps {
  columns: KanbanColumnProps[]
  className?: string
}

// ── KanbanCard ────────────────────────────────────────────────────────────────

export function KanbanCard({ item, className }: KanbanCardProps) {
  function handleDragStart(e: React.DragEvent<HTMLDivElement>) {
    e.dataTransfer.setData("application/json", JSON.stringify(item))
    e.dataTransfer.effectAllowed = "move"
  }

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      className={cn(
        "border-border bg-card cursor-grab select-none rounded-lg border p-3 shadow-sm active:cursor-grabbing",
        className,
      )}
    >
      <div className="flex items-start justify-between gap-2">
        <p className="text-foreground text-sm font-medium leading-snug">{item.title}</p>
        {item.badge && (
          <Badge variant="secondary" className="shrink-0 text-xs">
            {item.badge}
          </Badge>
        )}
      </div>
      {item.description && (
        <p className="text-muted-foreground mt-1.5 text-xs leading-relaxed">{item.description}</p>
      )}
    </div>
  )
}

// ── KanbanColumn ──────────────────────────────────────────────────────────────

export function KanbanColumn({ title, items, onDrop, className }: KanbanColumnProps) {
  const [isDragOver, setIsDragOver] = React.useState(false)

  function handleDragOver(e: React.DragEvent<HTMLDivElement>) {
    e.preventDefault()
    e.dataTransfer.dropEffect = "move"
    setIsDragOver(true)
  }

  function handleDragLeave() {
    setIsDragOver(false)
  }

  function handleDrop(e: React.DragEvent<HTMLDivElement>) {
    e.preventDefault()
    setIsDragOver(false)
    const raw = e.dataTransfer.getData("application/json")
    if (!raw) return
    try {
      const item = JSON.parse(raw) as KanbanItem
      onDrop?.(item, title)
    } catch {
      // Silently ignore invalid drag data
    }
  }

  return (
    <div
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={cn(
        "bg-muted/40 flex min-h-[200px] w-[280px] flex-col gap-2 rounded-xl p-3 transition-colors",
        isDragOver && "bg-muted/70 ring-primary/30 ring-2",
        className,
      )}
    >
      <div className="flex items-center justify-between px-1 pb-1">
        <h3 className="text-foreground text-sm font-semibold">{title}</h3>
        <span className="bg-muted text-muted-foreground rounded-full px-2 py-0.5 text-xs font-medium">
          {items.length}
        </span>
      </div>
      {items.map((item) => (
        <KanbanCard key={item.id} item={item} />
      ))}
      {items.length === 0 && (
        <div className="border-border text-muted-foreground flex flex-1 items-center justify-center rounded-lg border-2 border-dashed py-6 text-xs">
          Drop cards here
        </div>
      )}
    </div>
  )
}

// ── KanbanBoard ───────────────────────────────────────────────────────────────

export function KanbanBoard({ columns, className }: KanbanBoardProps) {
  return (
    <div
      className={cn("flex gap-4 overflow-x-auto pb-4", className)}
      role="region"
      aria-label="Kanban board"
    >
      {columns.map((col) => (
        <KanbanColumn
          key={col.title}
          title={col.title}
          items={col.items}
          {...(col.onDrop !== undefined ? { onDrop: col.onDrop } : {})}
          {...(col.className !== undefined ? { className: col.className } : {})}
        />
      ))}
    </div>
  )
}

import { Skeleton } from "@aetherstack/ui"
import { cn } from "@aetherstack/utils"

// ── Spinner ───────────────────────────────────────────────────────────────────

function Spinner({ className }: { className?: string }) {
  return (
    <svg
      className={cn("animate-spin", className)}
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
      aria-hidden="true"
    >
      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
      />
    </svg>
  )
}

// ── LoadingState ──────────────────────────────────────────────────────────────

export interface LoadingStateProps {
  /** "spinner" shows a centred spinner; "skeleton" shows skeleton rows */
  variant?: "spinner" | "skeleton"
  /** Number of skeleton rows (only used when variant="skeleton") */
  rows?: number
  text?: string
  className?: string
}

export function LoadingState({
  variant = "spinner",
  rows = 4,
  text = "Loading…",
  className,
}: LoadingStateProps) {
  if (variant === "skeleton") {
    return (
      <div className={cn("space-y-3 p-4", className)} aria-busy="true" aria-label={text}>
        {Array.from({ length: rows }).map((_, i) => (
          <div key={i} className="flex items-center gap-3">
            {i === 0 && <Skeleton className="h-9 w-9 shrink-0 rounded-full" />}
            <div className="flex-1 space-y-2">
              <Skeleton
                className={cn("h-4", i === 0 ? "w-3/4" : i % 2 === 0 ? "w-5/6" : "w-4/5")}
              />
              {i === 0 && <Skeleton className="h-3 w-1/2" />}
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div
      className={cn("flex flex-col items-center justify-center gap-3 py-16 text-center", className)}
      aria-busy="true"
      aria-label={text}
    >
      <Spinner className="text-primary h-8 w-8" />
      {text && <p className="text-muted-foreground text-sm">{text}</p>}
    </div>
  )
}

import * as React from "react"
import { Card, CardContent } from "@aetherstack/ui"
