          action={headerAction}
        />
      </div>

      {/* Content */}
      <div className="px-6 py-5">{children}</div>

      {/* Footer */}
      {footer && (
        <div className="border-border bg-muted/30 flex items-center justify-end gap-2 rounded-b-lg border-t px-6 py-3">
          {footer}
        </div>
      )}
