"use client"

import * as React from "react"
import useEmblaCarousel, { type UseEmblaCarouselType } from "embla-carousel-react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { cn } from "@aetherstack/utils"
import { Button } from "./button"

type CarouselApi = UseEmblaCarouselType[1]
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>
type CarouselOptions = UseCarouselParameters[0]
type CarouselPlugin = UseCarouselParameters[1]

type EmblaApi = NonNullable<CarouselApi>

interface CarouselProps {
  opts?: CarouselOptions
  plugins?: CarouselPlugin
  orientation?: "horizontal" | "vertical"
  setApi?: (api: CarouselApi) => void
}

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0]
  api: CarouselApi
  scrollPrev: () => void
  scrollNext: () => void
  canScrollPrev: boolean
  canScrollNext: boolean
} & CarouselProps

const CarouselContext = React.createContext<CarouselContextProps | null>(null)

function useCarousel() {
  const context = React.useContext(CarouselContext)
  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />")
  }
  return context
}

const Carousel = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & CarouselProps
>(({ orientation = "horizontal", opts, setApi, plugins, className, children, ...props }, ref) => {
  const [carouselRef, api] = useEmblaCarousel(
    { ...opts, axis: orientation === "horizontal" ? "x" : "y" },
    plugins,
  )
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)

  const onSelect = React.useCallback((emblaApi: EmblaApi) => {
    setCanScrollPrev(emblaApi.canScrollPrev())
    setCanScrollNext(emblaApi.canScrollNext())
  }, [])

  const scrollPrev = React.useCallback(() => api?.scrollPrev(), [api])
  const scrollNext = React.useCallback(() => api?.scrollNext(), [api])

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault()
        scrollPrev()
      } else if (event.key === "ArrowRight") {
        event.preventDefault()
        scrollNext()
      }
    },
    [scrollPrev, scrollNext],
  )

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on("reInit", onSelect)
    api.on("select", onSelect)
    return () => {
      api.off("select", onSelect)
      api.off("reInit", onSelect)
    }
  }, [api, onSelect])

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api,
        opts,
        orientation,
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}
    >
      <div
        ref={ref}
        onKeyDownCapture={handleKeyDown}
        className={cn("relative", className)}
        role="region"
        aria-roledescription="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  )
})
Carousel.displayName = "Carousel"

const CarouselContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const { carouselRef, orientation } = useCarousel()
    return (
      <div ref={carouselRef} className="overflow-hidden">
        <div
          ref={ref}
          className={cn(
            "flex",
            orientation === "horizontal" ? "-ml-4" : "-mt-4 flex-col",
            className,
          )}
          {...props}
        />
      </div>
    )
  },
)
CarouselContent.displayName = "CarouselContent"

const CarouselItem = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const { orientation } = useCarousel()
    return (
      <div
        ref={ref}
        role="group"
        aria-roledescription="slide"
        className={cn(
          "min-w-0 shrink-0 grow-0 basis-full",
          orientation === "horizontal" ? "pl-4" : "pt-4",
          className,
        )}
        {...props}
      />
    )
  },
)
CarouselItem.displayName = "CarouselItem"

const CarouselPrevious = React.forwardRef<HTMLButtonElement, React.ComponentProps<typeof Button>>(
  ({ className, variant = "outline", size = "icon", ...props }, ref) => {
    const { orientation, scrollPrev, canScrollPrev } = useCarousel()
    return (
      <Button
        ref={ref}
        variant={variant}
        size={size}
        className={cn(
          "absolute h-8 w-8 rounded-full",
          orientation === "horizontal"
            ? "-left-12 top-1/2 -translate-y-1/2"
            : "-top-12 left-1/2 -translate-x-1/2 rotate-90",
          className,
        )}
        disabled={!canScrollPrev}
        onClick={scrollPrev}
        {...props}
      >
        <ChevronLeft className="h-4 w-4" />
        <span className="sr-only">Previous slide</span>
      </Button>
    )
  },
)
CarouselPrevious.displayName = "CarouselPrevious"

const CarouselNext = React.forwardRef<HTMLButtonElement, React.ComponentProps<typeof Button>>(
  ({ className, variant = "outline", size = "icon", ...props }, ref) => {
    const { orientation, scrollNext, canScrollNext } = useCarousel()
    return (
      <Button
        ref={ref}
        variant={variant}
        size={size}
        className={cn(
          "absolute h-8 w-8 rounded-full",
          orientation === "horizontal"
            ? "-right-12 top-1/2 -translate-y-1/2"
            : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90",
          className,
        )}
        disabled={!canScrollNext}
        onClick={scrollNext}
        {...props}
      >
        <ChevronRight className="h-4 w-4" />
        <span className="sr-only">Next slide</span>
      </Button>
    )
  },
)
CarouselNext.displayName = "CarouselNext"

export { Carousel, CarouselContent, CarouselItem, CarouselPrevious, CarouselNext, useCarousel }
export type { CarouselApi }

"use client"

import * as React from "react"
import {
  BarChart as RechartsBarChart,
  Bar,
  LineChart as RechartsLineChart,
  Line,
  AreaChart as RechartsAreaChart,
  Area,
  PieChart as RechartsPieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  type TooltipProps,
} from "recharts"
import { cn } from "@aetherstack/utils"

type ChartRecord = Record<string, string | number>

export interface ChartSeries {
  dataKey: string
  color?: string
}

export interface ChartProps {
  data: ChartRecord[]
  series: ChartSeries[]
  height?: number
  className?: string
  showGrid?: boolean
  showLegend?: boolean
  showXAxis?: boolean
  showYAxis?: boolean
}

const CHART_COLORS = [
  "hsl(var(--chart-1))",
  "hsl(var(--chart-2))",
  "hsl(var(--chart-3))",
  "hsl(var(--chart-4))",
  "hsl(var(--chart-5))",
]

function resolveColor(series: ChartSeries, index: number): string {
  return series.color ?? CHART_COLORS[index % CHART_COLORS.length] ?? "hsl(var(--chart-1))"
}

function ChartTooltipContent({ active, payload, label }: TooltipProps<number | string, string>) {
  if (!active || !payload?.length) return null
  return (
    <div className="border-border bg-popover text-popover-foreground rounded-md border p-3 shadow-md">
      {label != null && <p className="text-muted-foreground mb-1.5 text-xs font-medium">{label}</p>}
      {payload.map((entry, i) => (
        <div
          key={`${String(entry.dataKey ?? entry.name)}-${i}`}
          className="flex items-center gap-2 text-sm"
        >
          <span className="inline-block h-2 w-2 rounded-full" style={{ background: entry.color }} />
          <span className="font-medium">{entry.name}</span>
          <span className="text-muted-foreground ml-auto pl-4 font-mono">{entry.value}</span>
        </div>
      ))}
    </div>
  )
}

function BarChart({
  data,
  series,
  height = 300,
  className,
  showGrid = true,
  showLegend = false,
  showXAxis = true,
  showYAxis = true,
}: ChartProps) {
  return (
    <div className={cn("w-full", className)}>
      <ResponsiveContainer width="100%" height={height}>
        <RechartsBarChart data={data}>
          {showGrid && <CartesianGrid strokeDasharray="3 3" className="stroke-border" />}
          {showXAxis && <XAxis dataKey="name" className="fill-muted-foreground text-xs" />}
          {showYAxis && <YAxis className="fill-muted-foreground text-xs" />}
          <Tooltip content={<ChartTooltipContent />} />
          {showLegend && <Legend />}
          {series.map((s, i) => (
            <Bar
              key={s.dataKey}
              dataKey={s.dataKey}
              fill={resolveColor(s, i)}
              radius={[4, 4, 0, 0]}
            />
          ))}
        </RechartsBarChart>
      </ResponsiveContainer>
    </div>
  )
}

function LineChart({
  data,
  series,
  height = 300,
  className,
  showGrid = true,
  showLegend = false,
  showXAxis = true,
  showYAxis = true,
}: ChartProps) {
  return (
    <div className={cn("w-full", className)}>
      <ResponsiveContainer width="100%" height={height}>
        <RechartsLineChart data={data}>
          {showGrid && <CartesianGrid strokeDasharray="3 3" className="stroke-border" />}
          {showXAxis && <XAxis dataKey="name" className="fill-muted-foreground text-xs" />}
          {showYAxis && <YAxis className="fill-muted-foreground text-xs" />}
          <Tooltip content={<ChartTooltipContent />} />
          {showLegend && <Legend />}
          {series.map((s, i) => (
            <Line
              key={s.dataKey}
              type="monotone"
              dataKey={s.dataKey}
              stroke={resolveColor(s, i)}
              strokeWidth={2}
              dot={false}
            />
          ))}
        </RechartsLineChart>
      </ResponsiveContainer>
    </div>
  )
}

function AreaChart({
  data,
  series,
  height = 300,
  className,
  showGrid = true,
  showLegend = false,
  showXAxis = true,
  showYAxis = true,
}: ChartProps) {
  return (
    <div className={cn("w-full", className)}>
      <ResponsiveContainer width="100%" height={height}>
        <RechartsAreaChart data={data}>
          {showGrid && <CartesianGrid strokeDasharray="3 3" className="stroke-border" />}
          {showXAxis && <XAxis dataKey="name" className="fill-muted-foreground text-xs" />}
          {showYAxis && <YAxis className="fill-muted-foreground text-xs" />}
          <Tooltip content={<ChartTooltipContent />} />
          {showLegend && <Legend />}
          {series.map((s, i) => {
            const color = resolveColor(s, i)
            return (
              <Area
                key={s.dataKey}
                type="monotone"
                dataKey={s.dataKey}
                stroke={color}
                fill={color}
                fillOpacity={0.15}
                strokeWidth={2}
              />
            )
          })}
        </RechartsAreaChart>
      </ResponsiveContainer>
    </div>
  )
}

export interface PieChartProps {
  data: { name: string; value: number; color?: string }[]
  height?: number
  className?: string
  showLegend?: boolean
}

function PieChart({ data, height = 300, className, showLegend = true }: PieChartProps) {
  return (
    <div className={cn("w-full", className)}>
      <ResponsiveContainer width="100%" height={height}>
        <RechartsPieChart>
          <Tooltip content={<ChartTooltipContent />} />
          {showLegend && <Legend />}
          <Pie data={data} cx="50%" cy="50%" outerRadius="80%" dataKey="value" label>
            {data.map((entry, index) => (
              <Cell
                key={`cell-${index}`}
                fill={entry.color ?? CHART_COLORS[index % CHART_COLORS.length]}
              />
            ))}
          </Pie>
        </RechartsPieChart>
      </ResponsiveContainer>
    </div>
  )
}

function DonutChart({ data, height = 300, className, showLegend = true }: PieChartProps) {
  return (
    <div className={cn("w-full", className)}>
      <ResponsiveContainer width="100%" height={height}>
        <RechartsPieChart>
          <Tooltip content={<ChartTooltipContent />} />
          {showLegend && <Legend />}
          <Pie data={data} cx="50%" cy="50%" innerRadius="50%" outerRadius="80%" dataKey="value">
            {data.map((entry, index) => (
              <Cell
                key={`cell-${index}`}
                fill={entry.color ?? CHART_COLORS[index % CHART_COLORS.length]}
              />
            ))}
          </Pie>
        </RechartsPieChart>
      </ResponsiveContainer>
    </div>
  )
}

interface ChartContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string
  description?: string
}

function ChartContainer({
  title,
  description,
  className,
  children,
  ...props
}: ChartContainerProps) {
  return (
    <div className={cn("border-border bg-card rounded-lg border p-4", className)} {...props}>
      {(title || description) && (
        <div className="mb-4">
          {title && <p className="text-sm font-semibold">{title}</p>}
          {description && <p className="text-muted-foreground text-xs">{description}</p>}
        </div>
      )}
      {children}
    </div>
  )
}

export { BarChart, LineChart, AreaChart, PieChart, DonutChart, ChartContainer }

import * as React from "react"
import { cn } from "@aetherstack/utils"

interface ChatBubbleProps {
  role: "user" | "assistant" | "system"
  content: React.ReactNode
  avatarUrl?: string
  name?: string
  timestamp?: string
  actions?: React.ReactNode
  className?: string
}

function ChatBubble({
  role,
  content,
  avatarUrl,
  name,
  timestamp,
  actions,
  className,
}: ChatBubbleProps) {
  if (role === "system") {
    return (
      <div data-role="system" className={cn("flex justify-center px-4", className)}>
        <div className="bg-muted text-muted-foreground max-w-[80%] rounded-full px-3 py-1 text-center text-xs [overflow-wrap:anywhere]">
          {content}
          {timestamp && <span className="ml-2 opacity-70">{timestamp}</span>}
        </div>
      </div>
    )
  }

  const isUser = role === "user"

  return (
    <div
      data-role={role}
      className={cn("group flex gap-3", isUser ? "flex-row-reverse" : "flex-row", className)}
    >
      {!isUser && (
        <div className="flex-shrink-0">
          {avatarUrl ? (
            <img
              src={avatarUrl}
              alt={name ? "" : "Assistant"}
              className="h-8 w-8 rounded-full object-cover"
            />
          ) : (
            <div
              aria-hidden="true"
              className="bg-muted text-muted-foreground flex h-8 w-8 items-center justify-center rounded-full text-xs font-medium"
            >
              {name ? name[0]?.toUpperCase() : "AI"}
            </div>
          )}
        </div>
      )}

      <div className={cn("flex min-w-0 max-w-[80%] flex-col gap-1", isUser && "items-end")}>
        {(name ?? timestamp) && (
          <div
            className={cn(
              "text-muted-foreground flex items-center gap-2 text-xs",
              isUser && "flex-row-reverse",
            )}
          >
            {name && <span className="font-medium">{name}</span>}
            {timestamp && <span>{timestamp}</span>}
          </div>
        )}

        <div
          className={cn(
            "max-w-full rounded-2xl px-4 py-2.5 text-sm [overflow-wrap:anywhere]",
            isUser
              ? "bg-primary text-primary-foreground rounded-tr-sm"
              : "bg-muted text-foreground rounded-tl-sm",
          )}
        >
          {content}
        </div>

        {actions && (
          <div className={cn("flex items-center gap-1", isUser && "flex-row-reverse")}>
            {actions}
          </div>
        )}
      </div>
    </div>
  )
}

export { ChatBubble }
export type { ChatBubbleProps }

