import { cn } from "@aetherstack/utils"
import { Progress } from "../progress"

interface TokenCounterProps {
  used: number
  max: number
  label?: string
  /** Fraction of `max` (0–1) at which the counter turns to a warning colour. Defaults to 0.8. */
  warnAt?: number
  className?: string
}

function TokenCounter({
  used,
  max,
  label = "Context window",
  warnAt = 0.8,
  className,
}: TokenCounterProps) {
  const ratio = max > 0 ? used / max : 0
  const percentage = Math.min(Math.max(ratio * 100, 0), 100)
  const level = ratio >= 1 ? "critical" : ratio >= warnAt ? "warning" : "normal"

  return (
    <div data-level={level} className={cn("flex flex-col gap-1.5", className)}>
      <div className="flex items-center justify-between gap-2 text-xs">
        <span className="text-muted-foreground">{label}</span>
        <span
          className={cn(
            "font-mono tabular-nums",
            level === "critical" && "text-destructive",
            level === "warning" && "text-amber-600 dark:text-amber-400",
            level === "normal" && "text-muted-foreground",
          )}
        >
          {used.toLocaleString()} / {max.toLocaleString()} tokens
        </span>
      </div>
      <Progress
        value={percentage}
        aria-label={label}
        getValueLabel={() => `${used.toLocaleString()} of ${max.toLocaleString()} tokens used`}
        className="h-1.5"
        indicatorClassName={cn(
          level === "critical" && "bg-destructive",
          level === "warning" && "bg-amber-500",
        )}
      />
    </div>
  )
}

export { TokenCounter }
export type { TokenCounterProps }

"use client"

import * as React from "react"
import { CircleCheck, CircleX, ChevronRight } from "lucide-react"
import { cn } from "@aetherstack/utils"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "../collapsible"

type ToolCallStatus = "pending" | "running" | "done" | "error"

interface ToolCallCardProps {
  toolName: string
  args?: Record<string, unknown>
  result?: unknown
  status: ToolCallStatus
  error?: string
  /** Execution time in milliseconds, shown next to the status. */
  duration?: number
  defaultOpen?: boolean
  className?: string
}

function formatPayload(value: unknown): string {
  if (typeof value === "string") return value
  try {
    return (
      JSON.stringify(value, (_key, v: unknown) => (typeof v === "bigint" ? v.toString() : v), 2) ??
      String(value)
    )
  } catch {
    return String(value)
  }
}

function formatDuration(ms: number): string {
  return ms < 1000 ? `${Math.round(ms)}ms` : `${(ms / 1000).toFixed(1)}s`
}

function ToolCallCard({
  toolName,
  args,
  result,
  status,
  error,
  duration,
  defaultOpen = false,
  className,
}: ToolCallCardProps) {
  const [open, setOpen] = React.useState(defaultOpen)
  const hasArgs = args !== undefined && Object.keys(args).length > 0
  const hasResult = result !== undefined && !error
  const hasDetails = hasArgs || hasResult || Boolean(error)

  const header = (
    <>
      <div className="flex min-w-0 items-center gap-2">
        <StatusIcon status={status} />
        <span className="truncate font-mono font-medium">{toolName}</span>
        <span
          className={cn(
            "shrink-0 text-xs capitalize",
            status === "error" ? "text-destructive" : "text-muted-foreground",
          )}
        >
          {status}
        </span>
        {duration !== undefined && (
          <span className="text-muted-foreground shrink-0 text-xs tabular-nums">
            · {formatDuration(duration)}
          </span>
        )}
      </div>
      {hasDetails && (
        <ChevronRight
          aria-hidden="true"
          className={cn(
            "text-muted-foreground h-4 w-4 shrink-0 transition-transform duration-200 motion-reduce:transition-none",
            open && "rotate-90",
          )}
        />
      )}
    </>
  )

  return (
    <Collapsible open={open} onOpenChange={setOpen} disabled={!hasDetails}>
      <div
        data-status={status}
        className={cn(
          "bg-card rounded-lg border",
          status === "error" ? "border-destructive/40" : "border-border",
          className,
        )}
      >
        {hasDetails ? (
          <CollapsibleTrigger asChild>
            <button
              type="button"
              className={cn(
                "flex w-full items-center justify-between gap-2 rounded-lg px-4 py-3 text-left text-sm",
                "ring-offset-background hover:bg-accent/50 transition-colors",
                "focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset",
              )}
            >
              {header}
            </button>
          </CollapsibleTrigger>
        ) : (
          <div className="flex w-full items-center justify-between gap-2 px-4 py-3 text-sm">
            {header}
          </div>
        )}

        <CollapsibleContent>
          <div className="border-border space-y-3 border-t px-4 pb-4 pt-3">
            {hasArgs && <PayloadSection label="Arguments" value={formatPayload(args)} />}
            {error && <PayloadSection label="Error" value={error} tone="destructive" />}
            {hasResult && <PayloadSection label="Result" value={formatPayload(result)} />}
          </div>
        </CollapsibleContent>
      </div>
    </Collapsible>
  )
}

function PayloadSection({
  label,
  value,
  tone = "default",
}: {
  label: string
  value: string
  tone?: "default" | "destructive"
}) {
  return (
    <div>
      <p
        className={cn(
          "mb-1 text-xs font-medium uppercase tracking-wide",
          tone === "destructive" ? "text-destructive" : "text-muted-foreground",
        )}
      >
        {label}
      </p>
      <pre
        tabIndex={0}
        className={cn(
          "max-h-64 overflow-auto whitespace-pre-wrap break-words rounded p-3 font-mono text-xs",
          "focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-2",
          tone === "destructive" ? "bg-destructive/10 text-destructive" : "bg-muted",
        )}
      >
        {value}
      </pre>
    </div>
  )
}

function StatusIcon({ status }: { status: ToolCallStatus }) {
  switch (status) {
    case "pending":
      return (
        <span
          aria-hidden="true"
          className="border-muted-foreground/40 h-4 w-4 shrink-0 rounded-full border-2"
        />
      )
    case "running":
      return (
        <span
          aria-hidden="true"
          className="border-primary h-4 w-4 shrink-0 animate-spin rounded-full border-2 border-t-transparent motion-reduce:animate-none"
        />
      )
    case "done":
      return (
        <CircleCheck
          aria-hidden="true"
          className="h-4 w-4 shrink-0 text-emerald-500 dark:text-emerald-400"
        />
      )
    case "error":
      return <CircleX aria-hidden="true" className="text-destructive h-4 w-4 shrink-0" />
  }
}

export { ToolCallCard }
export type { ToolCallCardProps, ToolCallStatus }

"use client"

import * as React from "react"
import { cn } from "@aetherstack/utils"

export type UptimeStatus = "up" | "degraded" | "down" | "unknown"

export interface UptimeDay {
  id: string
  label: string
  status: UptimeStatus
}

export interface UptimeBarProps {
  days: readonly UptimeDay[]
  onSelect?: (id: string) => void
  className?: string
}

const TONES: Record<UptimeStatus, string> = {
  up: "bg-emerald-500",
  degraded: "bg-amber-500",
  down: "bg-destructive",
  unknown: "bg-muted",
}

function uptimePercent(days: readonly UptimeDay[]): number {
  let known = 0
  let up = 0
  for (const day of days) {
    if (day.status === "unknown") continue
    known += 1
    if (day.status === "up") up += 1
  }
  if (known === 0) return 0
  return Math.round((up / known) * 100)
}

const focusRing =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"

export function UptimeBar({ days, onSelect, className }: UptimeBarProps) {
  const [active, setActive] = React.useState(0)
  const optionRefs = React.useRef<(HTMLButtonElement | null)[]>([])

  const percent = uptimePercent(days)
  const tabStopIndex = days.length === 0 ? 0 : Math.min(active, days.length - 1)

  const focusOption = (index: number) => {
    optionRefs.current[index]?.focus()
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>, index: number) => {
    if (days.length === 0) return

    if (event.key === "ArrowRight") {
      event.preventDefault()
      const next = Math.min(index + 1, days.length - 1)
      if (next !== index) {
        setActive(next)
        focusOption(next)
      }
      return
    }

    if (event.key === "ArrowLeft") {
      event.preventDefault()
      const next = Math.max(index - 1, 0)
      if (next !== index) {
        setActive(next)
        focusOption(next)
      }
      return
    }

    if (event.key === "Home") {
      event.preventDefault()
      setActive(0)
      focusOption(0)
      return
    }

    if (event.key === "End") {
      event.preventDefault()
      const last = days.length - 1
      setActive(last)
      focusOption(last)
      return
    }

    if ((event.key === "Enter" || event.key === " ") && onSelect) {
      event.preventDefault()
      const day = days[index]
      if (day) onSelect(day.id)
    }
  }

  return (
    <div
      role="listbox"
      aria-label={`${percent}% uptime`}
      className={cn(
        "border-border bg-background inline-flex w-full max-w-md gap-0.5 rounded-md border p-1",
        className,
      )}
    >
      {days.map((day, index) => (
        <button
          key={day.id}
          ref={(node) => {
            optionRefs.current[index] = node
          }}
          type="button"
          role="option"
          aria-label={`${day.label}, ${day.status}`}
          tabIndex={index === tabStopIndex ? 0 : -1}
          onFocus={() => setActive(index)}
          onKeyDown={(event) => handleKeyDown(event, index)}
          className={cn(
            "h-8 min-w-0 flex-1 rounded-sm transition-colors",
            TONES[day.status],
            focusRing,
          )}
        />
      ))}
    </div>
  )
}

